const fs=require('fs'),path=require('path'),http=require('http');const root=process.cwd(),out=__dirname;const {serveStaticFile}=require(path.join(root,'tools/verify/static-file-response.cjs'));const {launchOptions}=require(path.join(root,'tools/verify/browser-engines.cjs'));
(async()=>{const requests=[];const server=http.createServer((req,res)=>{if(req.url==='/clip.mp4'){requests.push({at:Date.now(),range:req.headers.range});return serveStaticFile(req,res,path.join(root,'examples/video-basic/assets/clip.mp4'),'video/mp4');}res.writeHead(200,{'Content-Type':'text/html'});res.end('<video width="320" height="240" playsinline preload="auto"></video><button>Run</button>');});await new Promise(r=>server.listen(0,'127.0.0.1',r));let browser;const records=[];try{browser=await require('playwright').webkit.launch({...launchOptions('webkit'),headless:true});for(const mode of ['from-start','paused-seek','recover-loop']){const page=await browser.newPage();await page.goto('http://127.0.0.1:'+server.address().port);await page.evaluate(mode=>{const v=document.querySelector('video');window.events=[];const start=performance.now();const state=()=>({ms:Math.round(performance.now()-start),time:v.currentTime,paused:v.paused,seeking:v.seeking,ended:v.ended,rate:v.playbackRate,ready:v.readyState});for(const event of ['play','playing','pause','waiting','seeking','seeked','ended','timeupdate','error'])v.addEventListener(event,()=>window.events.push({event,...state()}));v.muted=true;v.defaultMuted=true;v.src='/clip.mp4';const wait=async(f,ms)=>{const end=performance.now()+ms;while(performance.now()<end){if(f())return true;await new Promise(r=>setTimeout(r,20));}return false;};if(mode==='recover-loop'){let pending=false;v.addEventListener('pause',()=>{if(v.loop&&v.seeking&&v.currentTime<.1)pending=true;});v.addEventListener('seeked',()=>{if(pending&&v.loop&&v.paused&&v.currentTime<.1){pending=false;window.events.push({event:'resume-native-loop',...state()});v.play().catch(e=>window.events.push({event:'resume-error',error:String(e),...state()}));}});}document.querySelector('button').onclick=()=>{window.task=(async()=>{let prepared=true;if(mode==='from-start'){v.loop=true;await Promise.race([v.play(),new Promise((_,reject)=>setTimeout(()=>reject(Error('native play promise timeout')),3500))]).catch(e=>window.events.push({event:'play-rejected',error:String(e),...state()}));}else{if(mode==='ended-seek'){await Promise.race([v.play(),new Promise((_,reject)=>setTimeout(()=>reject(Error('native play promise timeout')),3500))]).catch(e=>window.events.push({event:'play-rejected',error:String(e),...state()}));prepared=await wait(()=>v.ended,5000);}v.pause();v.loop=true;v.currentTime=2;prepared=prepared&&await wait(()=>!v.seeking&&v.currentTime>=1.9&&v.currentTime<2.2,3000);await Promise.race([v.play(),new Promise((_,reject)=>setTimeout(()=>reject(Error('native play promise timeout')),3500))]).catch(e=>window.events.push({event:'play-rejected',error:String(e),...state()}));}const samples=[];for(let i=0;i<100;i++){samples.push(state());await new Promise(r=>setTimeout(r,80));}return {mode,prepared,samples,events:window.events};})();};},mode);await page.waitForFunction(()=>document.querySelector('video').readyState>=2);const clickedAt=Date.now();await page.getByRole('button',{name:'Run'}).click();const clickMs=Date.now()-clickedAt;const record=await page.evaluate(()=>window.task);records.push({...record,clickMs});fs.writeFileSync(path.join(out,'report.json'),JSON.stringify({browser:browser.version(),records,requests},null,2));console.log(JSON.stringify({mode,clickMs,events:record.events.filter(x=>x.event!=='timeupdate'),samples:record.samples.filter((_,i)=>i%15===0)}));await page.close();}}finally{await browser?.close();await new Promise(r=>server.close(r));}})().catch(e=>{console.error(e);process.exitCode=1;});


